def read_heat_rad_cav(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/HEAT/RAD_CAV/id`` or ``/HEAT/CAV/id`` (M205): Cavity radiation surface coupling."""
    from ..model.entities import HeatRadCav
    hid = block.user_id or 1
    title, cards = _fixed_data(block) if block.fixed else _title_and_data(block)
    surf_id1, surf_id2 = 0, 0
    emissivity1, emissivity2, view_factor = 1.0, 1.0, 1.0
    if cards and not cards[0].is_blank:
        if block.fixed:
            f = cards[0].cut("HEAT_RAD_CAV_1")
            surf_id1 = _ival(f[0]) if len(f) > 0 else 0
            surf_id2 = _ival(f[1]) if len(f) > 1 else 0
            emissivity1 = _fval(f[2], 1.0) if len(f) > 2 and f[2].strip() else 1.0
            emissivity2 = _fval(f[3], 1.0) if len(f) > 3 and f[3].strip() else 1.0
            view_factor = _fval(f[4], 1.0) if len(f) > 4 and f[4].strip() else 1.0
        else:
            t = cards[0].tokens()
            surf_id1 = int(float(t[0])) if len(t) > 0 else 0
            surf_id2 = int(float(t[1])) if len(t) > 1 else 0
            emissivity1 = float(t[2]) if len(t) > 2 else 1.0
            emissivity2 = float(t[3]) if len(t) > 3 else 1.0
            view_factor = float(t[4]) if len(t) > 4 else 1.0
    hrc = HeatRadCav(
        id=hid, title=title, surf_id1=surf_id1, surf_id2=surf_id2,
        emissivity1=emissivity1, emissivity2=emissivity2, view_factor=view_factor
    )
    model.heat_rad_cavs[hid] = hrc




def read_fail_fractal(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/FAIL/FRACTAL_DMG/mat_ID`` or ``/FAIL/FRACTAL/mat_ID`` (M118)::

        card 1:  grsh4n_1  grsh3n_1  grsh4n_2  grsh3n_2
        card 2:  Damage  Probability  Seed  Num_walk  Printout
        card 3:  fail_ID (optional)
    """
    cards = [c for c in (block.fixed_cards() if block.fixed else block.cards) if not c.is_blank]
    if not cards:
        log.error(f"/FAIL/FRACTAL_DMG/{block.user_id}: missing data card", block.source)
        return
    from ..model.entities import FailFractal, FailFractalDmg

    mat_id = block.user_id
    if len(block.parts) > 2:
        try:
            mat_id = int(block.parts[-1])
        except ValueError:
            pass

    if block.fixed:
        f1 = cards[0].cut("FAIL_FRACTAL_1")
        grsh4n_1 = _ival(f1[0]) if len(f1) > 0 else 0
        grsh3n_1 = _ival(f1[1]) if len(f1) > 1 else 0
        grsh4n_2 = _ival(f1[2]) if len(f1) > 2 else 0
        grsh3n_2 = _ival(f1[3]) if len(f1) > 3 else 0

        damage = 0.0
        probability = 0.0
        seed = 0
        num_walk = 0
        printout = 0
        if len(cards) > 1 and not cards[1].is_blank:
            f2 = cards[1].cut("FAIL_FRACTAL_2")
            damage = _fval(f2[0], 0.0) if len(f2) > 0 else 0.0
            probability = _fval(f2[1], 0.0) if len(f2) > 1 else 0.0
            seed = _ival(f2[2]) if len(f2) > 2 else 0
            num_walk = _ival(f2[3]) if len(f2) > 3 else 0
            printout = _ival(f2[4]) if len(f2) > 4 else 0

        fail_id = 0
        if len(cards) > 2 and not cards[2].is_blank:
            f3 = cards[2].cut("IDS10")
            fail_id = _ival(f3[0]) if len(f3) > 0 else 0
    else:
        t1 = cards[0].tokens()
        grsh4n_1 = int(float(t1[0])) if len(t1) > 0 else 0
        grsh3n_1 = int(float(t1[1])) if len(t1) > 1 else 0
        grsh4n_2 = int(float(t1[2])) if len(t1) > 2 else 0
        grsh3n_2 = int(float(t1[3])) if len(t1) > 3 else 0

        damage = 0.0
        probability = 0.0
        seed = 0
        num_walk = 0
        printout = 0
        if len(cards) > 1 and not cards[1].is_blank:
            t2 = cards[1].tokens()
            damage = float(t2[0]) if len(t2) > 0 else 0.0
            probability = float(t2[1]) if len(t2) > 1 else 0.0
            seed = int(float(t2[2])) if len(t2) > 2 else 0
            num_walk = int(float(t2[3])) if len(t2) > 3 else 0
            printout = int(float(t2[4])) if len(t2) > 4 else 0

        fail_id = 0
        if len(cards) > 2 and not cards[2].is_blank:
            t3 = cards[2].tokens()
            fail_id = int(float(t3[0])) if len(t3) > 0 else 0

    model.fail_fractals[mat_id] = FailFractal(
        mat_id=mat_id,
        grsh4n_1=grsh4n_1,
        grsh3n_1=grsh3n_1,
        grsh4n_2=grsh4n_2,
        grsh3n_2=grsh3n_2,
        damage=damage,
        probability=probability,
        seed=seed,
        num_walk=num_walk,
        printout=printout,
        fail_id=fail_id,
    )
    model.fails_fractal_dmg[mat_id] = FailFractalDmg(
        id=fail_id or mat_id,
        mat_id=mat_id,
        grsh4n_1=grsh4n_1,
        grsh3n_1=grsh3n_1,
        grsh4n_2=grsh4n_2,
        grsh3n_2=grsh3n_2,
        damage=damage,
        probability=probability,
        seed=seed,
        num_walk=num_walk,
        printout=printout,
        fail_id=fail_id,
        title="",
    )
    from ..model.entities import FailureModel
    fm = FailureModel(type="FRACTAL", ifail_sh=1, params={
        "grsh4n_1": grsh4n_1, "grsh3n_1": grsh3n_1, "grsh4n_2": grsh4n_2, "grsh3n_2": grsh3n_2,
        "damage": damage, "probability": probability, "seed": seed, "num_walk": num_walk, "printout": printout
    })
    model.raw_fails.append((mat_id, fm, block.source))


def read_fail(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/FAIL/JOHNSON/mat_ID`` and ``/FAIL/BIQUAD/mat_ID``: attach a
    failure criterion to a material (the trailing id IS the material id —
        card 2:  eps_dot_0   Ifail_sh        (optional; defaults 1.0, 1)

      eps_f = (D1 + D2*exp(D3*sigma*)) * (1 + D4*ln(rate/eps_dot_0))
              * (1 + D5*T*),
      damage D += d_eps_p/eps_f, break at D >= 1. Ifail_sh: 1 = delete
      the shell when ONE layer breaks (default), 2 = when ALL layers do.
      D5 (M6) needs the material's adiabatic temperature (the LAW2
      thermal card) — the Starter warns and drops it otherwise.

    BIQUAD — Fortran starter/source/materials/fail/biquad::

        card 1:  c1   c2   c3   c4   c5
        card 2:  Ifail_sh                    (optional; default 1)

      failure plastic strains at triaxialities -1/3, 0, 1/3, 2/3, 1 —
      two parabolas through them (see pyradioss/failure/biquad.py). The
      M-flag material presets and S-flag of the original are not ported:
      give the five coefficients explicitly.

    Solids break when their single integration point does (the ported
    hexa/tetra are one-point elements, so the original's Ifail_so
    variants are moot here).
    """
    from ..failure import biquad as fail_biquad
    from ..model.entities import FailureModel
    kind = block.parts[1].upper() if len(block.parts) > 1 else ""
    if kind in ("TSAI-WU", "TSAI_WU"):
        kind = "TSAIWU"
    elif kind in ("TSAI-HILL", "TSAI_HILL"):
        kind = "TSAIHILL"
    elif kind in ("MAX_STRAIN",):
        kind = "MAXSTRAIN"
    elif kind in ("ORTH_BIQUAD",):
        kind = "ORTHBIQUAD"
    elif kind in ("HC_DSSE", "HC-DSSE", "HCDSSE") or (kind == "HC" and len(block.parts) > 2 and block.parts[2].upper() == "DSSE"):
        kind = "HC_DSSE"
    elif kind in ("MULLINS", "MULLINS_OR", "MULLINS-OR"):
        kind = "MULLINS_OR"
    elif kind in ("SNCONNECT", "SN_CONNECT", "SN-CONNECT"):
        kind = "SNCONNECT"
    elif kind in ("SPALL", "SPALLING"):
        kind = "SPALLING"
    elif kind in ("LADEVEZE", "LAD_DAMA"):
        kind = "LAD_DAMA"
    elif kind in ("MMC", "WIERZBICKI"):
        kind = "WIERZBICKI"
    elif kind in ("XFEM_FLD", "XFEM/FLD") or (kind == "XFEM" and len(block.parts) > 2 and block.parts[2].upper() == "FLD"):
        kind = "XFEM_FLD"
    elif kind in ("XFEM_JOHNS", "XFEM/JOHNS") or (kind == "XFEM" and len(block.parts) > 2 and block.parts[2].upper() in ("JOHNS", "JOHNSON")):
        kind = "XFEM_JOHNS"
    elif kind in ("XFEM_TBUTC", "XFEM/TBUTC") or (kind == "XFEM" and len(block.parts) > 2 and block.parts[2].upper() in ("TBUTC", "TBUTCHER")):
        kind = "XFEM_TBUTC"

    elif kind in ("TENSTRAIN", "TENSSTRAIN"):
        kind = "TENSSTRAIN"
    elif kind in ("USER", "FAIL_USER"):
        kind = "USER"
    elif kind in ("PUCK", "PUCK_MODEL", "PUCK_LAW", "PUCK_CRITERION"):
        kind = "PUCK"
    elif kind in ("RTCL", "RTCL_MODEL", "RTCL_LAW"):
        kind = "RTCL"
    elif kind in ("SAHRAEI", "SAHRAEI_MODEL", "SAHRAEI_LAW", "BATTERY_SEPARATOR"):
        kind = "SAHRAEI"
    elif kind in ("SYAZWAN", "SYAZWAN_MODEL", "SYAZWAN_LAW"):
        kind = "SYAZWAN"
    elif kind in ("GURSON", "GURSON_MODEL", "GURSON_LAW", "GURSON_TVERGAARD_NEEDLEMAN", "GURSON_DAMAGE"):
        kind = "GURSON"

    if kind not in ("JOHNSON", "BIQUAD", "ORTHBIQUAD", "TAB1", "SNCONNECT", "FLD", "CONNECT",
                    "TENSSTRAIN", "ORTHSTRAIN", "GURSON", "ALTER", "VISUAL", "MULLINS_OR", "MULLINS",
                    "PUCK", "RTCL", "SAHRAEI", "SYAZWAN", "TAB2", "GENE1", "INIEVO",
                    "CHANG", "TSAIWU", "TSAIHILL", "HOFFMAN", "MAXSTRAIN", "HASHIN",
                    "LEMAITRE", "COCKCROFT", "ENERGY", "COMPOSITE", "FRACTAL", "FRACTAL_DMG",
                    "ORTHENERG", "EMC", "FABRIC", "SPALLING", "SPALL", "TBUTCHER", "WIERZBICKI", "WILKINS",
                    "NXT", "LAD_DAMA", "XFEM_FLD", "XFEM_JOHNS", "XFEM_TBUTC", "HC_DSSE", "USER",
                    # M210-M244 failure criteria:
                    "TBID", "TABLE", "FAIL_TBID",
                    "SN_CURVE", "SNCURVE", "SN", "WOHLER", "FATIGUE_SN",
                    "HOOP", "HOOP_STRESS", "PIPE_HOOP",
                    "SPALLING_CUT", "SPALL_CUT", "HYDRO_CUT",
                    "VOIDS", "VOID", "POROSITY",
                    "HC", "HOSFORD_COULOMB", "HOSFORD",
                    "LAD_EVR", "LADEVEZE_EVR", "LAD_EVR_COMP",
                    "ORTHO", "ORTHOTROPIC", "LAMINA",
                    "COHESIVE", "COH", "INTERFACE",
                    "MAX_STRESS", "MAXSTRESS", "MAX_TENS",
                    "SNOW", "BRITTLE_SNOW",
                    "VISCO", "VISCO_PLASTIC", "VISCOUS",
                    "BAMMAN", "BCJ", "BAMMAN_CHIESA_JOHNSON",
                    "WEIBULL", "WEIBULL_BRITTLE",
                    "PU", "POLYURETHANE",
                    "GRIFFITH", "GRIF",
                    "DRUCKER", "DRUCKER_PRAGER", "DP",
                    "WOOD", "TIMBER", "ORTH_WOOD",
                    "HILL", "HILL_PLASTIC", "HILL48",
                    "NORTON", "CREEP", "NORTON_CREEP",
                    "MOHR", "MOHR_COULOMB", "MC",
                    "LUSAS", "COMPOSITE_LUSAS", "LUSAS_COMPOSITE",
                    "GTN", "GURSON_TVERGAARD", "GURSON_POROUS",
                    "TAB3", "TABULATED3", "TAB_3D",
                    "CHABOCHE", "LEMAITRE_CHABOCHE", "CHABOCHE_DAMAGE",
                    "GURSON_MODEL", "GURSON_DAMAGE",
                    "TVERGAARD", "TVERGAARD_NEEDLEMAN", "TN",
                    "HENCKY", "HENCKY_STRAIN", "LOG_STRAIN",
                    "ENERGY_DENSITY", "SED", "STRAIN_ENERGY_DENSITY",
                    "ENERGY_RATIO", "ERATIO", "SPECIFIC_ENERGY",
                    "RICE_TRACEY", "RT", "VOID_GROWTH",
                    "BAO_WIERZBICKI", "BW", "BAO_WIEZBICKI", "BAO",
                    "LOU_HUHN", "LH", "LOU_HUHN_MODEL", "LOU",
                    "HOLLOMON", "HOLLOMON_DAMAGE", "POWER_LAW", "HOLLOMON_LAW",
                    "SWIFT", "SWIFT_LAW", "SWIFT_DAMAGE", "SWIFT_MODEL"):
        log.warning(f"/FAIL/{kind} not ported — skipped "
                    f"(supported: JOHNSON, BIQUAD, ORTHBIQUAD, TAB1, SNCONNECT, FLD, CONNECT, "
                    f"TENSSTRAIN, ORTHSTRAIN, GURSON, ALTER, VISUAL, MULLINS_OR, "
                    f"PUCK, RTCL, SAHRAEI, SYAZWAN, TAB2, GENE1, INIEVO, "
                    f"CHANG, TSAIWU, TSAIHILL, HOFFMAN, MAXSTRAIN, HASHIN, "
                    f"LEMAITRE, COCKCROFT, ENERGY, COMPOSITE, FRACTAL, FRACTAL_DMG, "
                    f"ORTHENERG, EMC, FABRIC, SPALLING, TBUTCHER, WIERZBICKI, WILKINS, "
                    f"NXT, LAD_DAMA, XFEM_FLD, XFEM_JOHNS, XFEM_TBUTC, HC_DSSE, USER, "
                    f"plus M210-M244 criteria)", block.source)
        return

    # header /FAIL/<kind>/mat_ID[/fail_ID]: with TWO trailing ids the
    # FIRST is the material id (the lexer keeps only the last as user_id)
    mat_id = block.user_id
    if kind == "HC_DSSE" and len(block.parts) > 2 and block.parts[1].upper() == "HC" and block.parts[2].upper() == "DSSE":
        if len(block.parts) > 4:
            try:
                mat_id = int(block.parts[3])
            except ValueError:
                pass
        elif len(block.parts) > 3:
            try:
                mat_id = int(block.parts[3])
            except ValueError:
                pass
    elif len(block.parts) > 3:
        try:
            mat_id = int(block.parts[2])
        except ValueError:
            pass
    title, cards = _title_and_data(block)
    if not cards:
        if kind in ("GURSON", "FAIL_GURSON", "GURSON_MODEL", "GURSON_LAW", "GURSON_TVERGAARD_NEEDLEMAN"):
            read_fail_gurson(block, model, log)
            return
        log.error(f"/FAIL/{kind}/{mat_id}: missing data card", block.source)
        return
    if kind in ("FRACTAL", "FRACTAL_DMG"):
        read_fail_fractal(block, model, log)
        return
    if kind in ("TBID", "TABLE", "FAIL_TBID"):
        read_fail_tbid(block, model, log)
        return
    if kind in ("SN_CURVE", "SNCURVE", "SN", "WOHLER", "FATIGUE_SN"):
        read_fail_sn_curve(block, model, log)
        return
    if kind in ("HOOP", "HOOP_STRESS", "PIPE_HOOP"):
        read_fail_hoop(block, model, log)
        return
