    if kind in ("LAD_VISCO_DAMAGE", "FAIL_LAD_VISCO_DAMAGE", "LADEVEZE_VISCO_DAMAGE", "LAD_VD", "LAD_VD_MODEL", "LAD_VD_LAW", "LADEVEZE_RATE_DEPENDENT_MICRODAMAGE"):
        read_fail_lad_visco_damage(block, model, log)
