    fct_mtout, fct_mpout, fscale_mtout, fscale_mpout = 0, 0, 1.0, 1.0
    fct_padd, fct_pmax, fscale_padd, fscale_pmax = 0, 0, 1.0, 1.0

    if block.fixed:
        f1 = cards[0].cut("MONVOL_LFLUID_1")
