            nu = float(t2[1]) if len(t2) > 1 else 0.0
            ires = int(float(t2[2])) if len(t2) > 2 else 0
            ivisc = int(float(t2[3])) if len(t2) > 3 else 0
            fcut = float(t2[4]) if len(t2) > 4 else 0.0
