            r22 = _safe_float(c4[1], 1.0) if len(c4) > 1 else 1.0
            r12 = _safe_float(c4[2], 1.0) if len(c4) > 2 else 1.0
            r33 = _safe_float(c4[3], 1.0) if len(c4) > 3 else 1.0
