    model.materials[mat_id] = Material(
        id=mat_id, law=133, rho0=rho0, title=title,
        params={
            "rho": rho0, "rhor": rhor, "nu": nu, "pmin": pmin,
            "fct_id_g": fct_id_g, "fscale_g": fscale_g, "fct_id_y": fct_id_y, "fscale_y": fscale_y,
        }
    )


