        f = cards[0].cut("FAIL_SN_1")
        fct_id = _ival(f[0]) if len(f) > 0 else 0
        ifail_sh = _ival(f[1], 1) if len(f) > 1 else 1
        s_mean_corr = _ival(f[2], 0) if len(f) > 2 else 0
        d_crit = _fval(f[3], 1.0) if len(f) > 3 else 1.0
