def read_prop_type13(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/PROP/TYPE13`` or ``/PROP/SPR_PULL`` (M194): Pulling spring property."""
    from ..model.entities import PropType13, Property
