    params = {}
    if len(valid_cards) > 0:
        c0 = valid_cards[0].tokens()
        stiff = _safe_float(c0[0]) if len(c0) > 0 else 0.0
        f_max = _safe_float(c0[1]) if len(c0) > 1 else 0.0
