def read_fail_lad_str(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/FAIL/LAD_STR/mat_ID`` or ``/FAIL/LADEVEZE_STRESS`` (M286): Ladevèze stress-based composite damage and ply failure criterion."""
    title, cards = _title_and_data(block)
    if not cards or cards[0].is_blank:
        log.error(f"/FAIL/LAD_STR/{block.user_id}: missing data card", block.source)
        return
    mat_id = block.user_id
    if block.fixed:
        c1 = cards[0].cut("FAIL_LAD_STR_1")
        r0_1 = _fval(c1[0]) if len(c1) > 0 else 0.0
        r0_2 = _fval(c1[1]) if len(c1) > 1 else 0.0
        rc_1 = _fval(c1[2]) if len(c1) > 2 else 0.0
        rc_2 = _fval(c1[3]) if len(c1) > 3 else 0.0
        b_lad = _fval(c1[4]) if len(c1) > 4 else 0.0
        c2 = cards[1].cut("FAIL_LAD_STR_2") if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = _ival(c2[0], 1) if len(c2) > 0 else 1
        ifail_so = _ival(c2[1], 1) if len(c2) > 1 else 1
    else:
        t1 = cards[0].tokens()
        r0_1 = float(t1[0].rstrip(',')) if len(t1) > 0 else 0.0
        r0_2 = float(t1[1].rstrip(',')) if len(t1) > 1 else 0.0
        rc_1 = float(t1[2].rstrip(',')) if len(t1) > 2 else 0.0
        rc_2 = float(t1[3].rstrip(',')) if len(t1) > 3 else 0.0
        b_lad = float(t1[4].rstrip(',')) if len(t1) > 4 else 0.0
        t2 = cards[1].tokens() if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = int(float(t2[0].rstrip(','))) if len(t2) > 0 else 1
        ifail_so = int(float(t2[1].rstrip(','))) if len(t2) > 1 else 1
    fail_id = 0
    if len(cards) > 2 and not cards[2].is_blank:
        fail_id = _ival(cards[2].cut("FAIL_RTCL_2")[0]) if block.fixed else int(float(cards[2].tokens()[0].rstrip(',')))
    params = {
        "r0_1": r0_1, "r0_2": r0_2, "rc_1": rc_1, "rc_2": rc_2, "b_lad": b_lad,
        "ifail_sh": ifail_sh, "ifail_so": ifail_so, "fail_id": fail_id,
    }
    from ..model.entities import FailLadStr, FailureModel
    model.fail_ladstrs[mat_id] = FailLadStr(
        mat_id=mat_id, title=title, r0_1=r0_1, r0_2=r0_2, rc_1=rc_1, rc_2=rc_2, b_lad=b_lad,
        ifail_sh=ifail_sh, ifail_so=ifail_so, fail_id=fail_id,
    )
    fm = FailureModel(type="LAD_STR", ifail_sh=ifail_sh, params=params)
    model.raw_fails.append((mat_id, fm, block.source))


