def read_fail_lad_fracture(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/FAIL/LAD_FRACTURE/mat_ID`` or ``/FAIL/LADEVEZE_DYNAMIC_FRACTURE`` (M302): Ladevèze dynamic microcrack coalescence and cohesive zone fracture transition failure model."""
    title, cards = _title_and_data(block)
    if not cards or cards[0].is_blank:
        log.error(f"/FAIL/LAD_FRACTURE/{block.user_id}: missing data card", block.source)
        return
    mat_id = block.user_id
    if block.fixed:
        c1 = cards[0].cut("FAIL_LAD_FRACTURE_1")
        y0_frac = _fval(c1[0], 0.0) if len(c1) > 0 and c1[0].strip() else 0.0
        yc_frac = _fval(c1[1], 0.0) if len(c1) > 1 and c1[1].strip() else 0.0
        gamma_cohes = _fval(c1[2], 0.0) if len(c1) > 2 and c1[2].strip() else 0.0
        l_char = _fval(c1[3], 0.0) if len(c1) > 3 and c1[3].strip() else 0.0
        d_frac_max = _fval(c1[4], 0.999) if len(c1) > 4 and c1[4].strip() else 0.999
        c2 = cards[1].cut("FAIL_LAD_FRACTURE_2") if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = _ival(c2[0], 1) if len(c2) > 0 else 1
        ifail_so = _ival(c2[1], 1) if len(c2) > 1 else 1
    else:
        t1 = cards[0].tokens()
        y0_frac = float(t1[0].rstrip(',')) if len(t1) > 0 and t1[0].rstrip(',') else 0.0
        yc_frac = float(t1[1].rstrip(',')) if len(t1) > 1 and t1[1].rstrip(',') else 0.0
        gamma_cohes = float(t1[2].rstrip(',')) if len(t1) > 2 and t1[2].rstrip(',') else 0.0
        l_char = float(t1[3].rstrip(',')) if len(t1) > 3 and t1[3].rstrip(',') else 0.0
        d_frac_max = float(t1[4].rstrip(',')) if len(t1) > 4 and t1[4].rstrip(',') else 0.999
        t2 = cards[1].tokens() if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = int(float(t2[0].rstrip(','))) if len(t2) > 0 else 1
        ifail_so = int(float(t2[1].rstrip(','))) if len(t2) > 1 else 1
    fail_id = 0
    if len(cards) > 2 and not cards[2].is_blank:
        fail_id = _ival(cards[2].cut("FAIL_RTCL_2")[0]) if block.fixed else int(float(cards[2].tokens()[0].rstrip(',')))
    params = {
        "y0_frac": y0_frac, "yc_frac": yc_frac, "gamma_cohes": gamma_cohes,
        "l_char": l_char, "d_frac_max": d_frac_max,
        "ifail_sh": ifail_sh, "ifail_so": ifail_so, "fail_id": fail_id,
    }
    from ..model.entities import FailLadFracture, FailureModel
    model.fail_ladfractures[mat_id] = FailLadFracture(
        mat_id=mat_id, title=title, y0_frac=y0_frac, yc_frac=yc_frac,
        gamma_cohes=gamma_cohes, l_char=l_char, d_frac_max=d_frac_max,
        ifail_sh=ifail_sh, ifail_so=ifail_so, fail_id=fail_id,
    )
    fm = FailureModel(type="LAD_FRACTURE", ifail_sh=ifail_sh, params=params)
    model.raw_fails.append((mat_id, fm, block.source))


