        c1 = cards[0].cut("FAIL_LAD_TRANSVERSE_COMPRESSION_1")
        y0_tc = _fval(c1[0], 0.0) if len(c1) > 0 and c1[0].strip() else 0.0
        yc_tc = _fval(c1[1], 0.0) if len(c1) > 1 and c1[1].strip() else 0.0
