    title, cards = _title_and_data(block)
    if not cards or cards[0].is_blank:
        log.error(f"/FAIL/LAD_FIBER_MATRIX_DEBOND_RATE/{block.user_id}: missing data card", block.source)
        return
    mat_id = block.user_id
    if block.fixed:
        c1 = cards[0].cut("FAIL_LAD_FIBER_MATRIX_DEBOND_RATE_1")
        y0_fmdr = _fval(c1[0], 0.0) if len(c1) > 0 and c1[0].strip() else 0.0
        yc_fmdr = _fval(c1[1], 0.0) if len(c1) > 1 and c1[1].strip() else 0.0
