        f1 = cards[0].cut("HOMOLOGICAL_SPINOR_SPATIAL_LINKAGE_JOINT_1")
        node1 = _ival(f1[0], 0) if len(f1) > 0 else 0
        node2 = _ival(f1[1], 0) if len(f1) > 1 else 0
