    mat_id = block.user_id
    if block.fixed:
        c1 = cards[0].cut("FAIL_LAD_TRANSVERSE_TENSION_RATE_1")
        y0_ttr = _fval(c1[0], 0.0) if len(c1) > 0 and c1[0].strip() else 0.0
