    """``/FAIL/LAD_COUPLE_PLASTICITY/mat_ID`` or ``/FAIL/LADEVEZE_COUPLED_PLASTICITY`` (M326): Ladevèze coupled continuum damage and plasticity hardening failure model."""
    title, cards = _title_and_data(block)
    if not cards or cards[0].is_blank:
        log.error(f"/FAIL/LAD_COUPLE_PLASTICITY/{block.user_id}: missing data card", block.source)
        return
    mat_id = block.user_id
    if block.fixed:
        c1 = cards[0].cut("FAIL_LAD_COUPLE_PLASTICITY_1")
        r_p0 = _fval(c1[0], 0.0) if len(c1) > 0 and c1[0].strip() else 0.0
        k_p = _fval(c1[1], 0.0) if len(c1) > 1 and c1[1].strip() else 0.0
        m_p = _fval(c1[2], 1.0) if len(c1) > 2 and c1[2].strip() else 1.0
        gamma_d = _fval(c1[3], 0.0) if len(c1) > 3 and c1[3].strip() else 0.0
        d_cp_max = _fval(c1[4], 0.999) if len(c1) > 4 and c1[4].strip() else 0.999
        c2 = cards[1].cut("FAIL_LAD_COUPLE_PLASTICITY_2") if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = _ival(c2[0], 1) if len(c2) > 0 else 1
        ifail_so = _ival(c2[1], 1) if len(c2) > 1 else 1
    else:
        t1 = cards[0].tokens()
        r_p0 = float(t1[0].rstrip(',')) if len(t1) > 0 and t1[0].rstrip(',') else 0.0
        k_p = float(t1[1].rstrip(',')) if len(t1) > 1 and t1[1].rstrip(',') else 0.0
        m_p = float(t1[2].rstrip(',')) if len(t1) > 2 and t1[2].rstrip(',') else 1.0
        gamma_d = float(t1[3].rstrip(',')) if len(t1) > 3 and t1[3].rstrip(',') else 0.0
