def read_fail_lad_couple_delamination_rate(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/FAIL/LAD_COUPLE_DELAMINATION_RATE/mat_ID`` or ``/FAIL/LADEVEZE_COUPLED_DELAMINATION_RATE`` (M337): Ladevèze rate-dependent coupled interlaminar delamination and matrix micro-cracking failure model."""
    title, cards = _title_and_data(block)
    if not cards or cards[0].is_blank:
        log.error(f"/FAIL/LAD_COUPLE_DELAMINATION_RATE/{block.user_id}: missing data card", block.source)
        return
    mat_id = block.user_id
    if block.fixed:
        c1 = cards[0].cut("FAIL_LAD_COUPLE_DELAMINATION_RATE_1")
        sigma_cdel0 = _fval(c1[0], 0.0) if len(c1) > 0 and c1[0].strip() else 0.0
        sigma_cdelc = _fval(c1[1], 1.0) if len(c1) > 1 and c1[1].strip() else 1.0
        gamma_cdel = _fval(c1[2], 0.0) if len(c1) > 2 and c1[2].strip() else 0.0
        p_cdel = _fval(c1[3], 1.0) if len(c1) > 3 and c1[3].strip() else 1.0
        d_cdel_max = _fval(c1[4], 0.999) if len(c1) > 4 and c1[4].strip() else 0.999
        c2 = cards[1].cut("FAIL_LAD_COUPLE_DELAMINATION_RATE_2") if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = _ival(c2[0], 1) if len(c2) > 0 else 1
        ifail_so = _ival(c2[1], 1) if len(c2) > 1 else 1
    else:
        t1 = cards[0].tokens()
        sigma_cdel0 = float(t1[0].rstrip(',')) if len(t1) > 0 and t1[0].rstrip(',') else 0.0
        sigma_cdelc = float(t1[1].rstrip(',')) if len(t1) > 1 and t1[1].rstrip(',') else 1.0
        gamma_cdel = float(t1[2].rstrip(',')) if len(t1) > 2 and t1[2].rstrip(',') else 0.0
        p_cdel = float(t1[3].rstrip(',')) if len(t1) > 3 and t1[3].rstrip(',') else 1.0
        d_cdel_max = float(t1[4].rstrip(',')) if len(t1) > 4 and t1[4].rstrip(',') else 0.999
        t2 = cards[1].tokens() if len(cards) > 1 and not cards[1].is_blank else []
        ifail_sh = int(float(t2[0].rstrip(','))) if len(t2) > 0 else 1
        ifail_so = int(float(t2[1].rstrip(','))) if len(t2) > 1 else 1
    fail_id = 0
    if len(cards) > 2 and not cards[2].is_blank:
        fail_id = _ival(cards[2].cut("FAIL_RTCL_2")[0]) if block.fixed else int(float(cards[2].tokens()[0].rstrip(',')))
    params = {
        "sigma_cdel0": sigma_cdel0, "sigma_cdelc": sigma_cdelc, "gamma_cdel": gamma_cdel,
        "p_cdel": p_cdel, "d_cdel_max": d_cdel_max,
        "ifail_sh": ifail_sh, "ifail_so": ifail_so, "fail_id": fail_id,
    }
    from ..model.entities import FailLadCoupleDelaminationRate, FailureModel
    model.fail_ladcoupledelaminationrates[mat_id] = FailLadCoupleDelaminationRate(
        mat_id=mat_id, title=title, sigma_cdel0=sigma_cdel0, sigma_cdelc=sigma_cdelc,
        gamma_cdel=gamma_cdel, p_cdel=p_cdel, d_cdel_max=d_cdel_max,
        ifail_sh=ifail_sh, ifail_so=ifail_so, fail_id=fail_id,
    )
    fm = FailureModel(type="LAD_COUPLE_DELAMINATION_RATE", ifail_sh=ifail_sh, params=params)
    model.raw_fails.append((mat_id, fm, block.source))


