ENGINE_KEYWORDS_IGNORE = {
    # Engine-only keywords that should be silently skipped in the Starter.
    # Keys already in KEYWORD_PARSERS are handled by their own parser and
    # are NOT listed here (KEYWORD_PARSERS is checked first in dispatch).
    "ANIM", "DEBUG", "DT", "DTIX", "MON",
}

def parse_starter_deck(blocks: Union[List[KeywordBlock], str, Any],
                       model: Optional[Model] = None,
                       log: Optional[MessageLog] = None) -> Model:
    """Dispatch every block to its parser (unknown → warning + skip).

    M37: blocks whose header carries a LOCAL unit id
    (``/KEY/.../user_ID/unit_ID``) are recorded in
    ``model.raw_unit_refs`` — the unit conversion into the /BEGIN work
    system happens in the Starter resolve phase (input/units.py), after
    all /UNIT blocks are read (deck order between a block and the /UNIT
    it references is free, like every other cross-reference)."""
    if isinstance(blocks, str) or hasattr(blocks, "__fspath__"):
        from .deck_reader import read_deck
        blocks = read_deck(str(blocks))
    if model is None:
        model = Model()
    if log is None:
        log = MessageLog()
    for block in blocks:
        # M258: handle missing #include files (FileNotFoundError → error, not crash)
        if block.keyword == "__INCLUDE_ERROR__":
            inc_path = getattr(block, "_include_path", "?")
            log.error(f"#include file not found: {inc_path}", block.source)
            continue
        joined_key = "_".join(block.parts).upper() if block.parts else block.key0
        parser = KEYWORD_PARSERS.get(joined_key)
        if parser is None and len(block.parts) > 1:
            joined_key2 = "_".join(block.parts[:2]).upper()
            parser = KEYWORD_PARSERS.get(joined_key2)
        if parser is None:
            parser = KEYWORD_PARSERS.get(block.key0)
        if parser is None:
            if block.key0 in ENGINE_KEYWORDS_IGNORE:
                # Silently bypass engine output requests and control flags
                # that often slip into shared input decks. The engine will
                # parse them later if they are in the engine deck.
                continue
            log.warning(f"keyword /{'/'.join(block.parts)} not ported — "
                        f"block skipped", block.source)
            continue
        try:
            parser(block, model, log)
        except (ValueError, IndexError, KeyError) as exc:
            log.error(f"while reading /{'/'.join(block.parts)}: {exc}",
                      block.source)
            continue
        if block.unit_id is not None and block.key0 not in (
            "FAIL", "ADMAS", "TABLE", "INIVOL", "INIBRI", "INISHE", "INISH3",
            "INITRU", "INITRUSS", "INIBEA", "INIBEAM", "INISPR", "INISPRI",
            "SET", "SETS", "STATE", "CHECKSUM", "DYNAIN", "SECT", "EBCS",
            "INIQUA", "INIQUAD", "INISTA", "INISTATE", "SPH_RESERVE", "MOVE_FUNCT",
            "EIG", "SHFRA", "SHFRA_V4", "INTTHICK", "INT_THICK", "STR_FILE", "MEMORY", "PLOAD",
            "ARCH", "ALTDOCTAG", "EXTERN", "EXTLNK", "SUBDOMAIN",
            "FUNCT_PYTHON", "PYTHON_FUNCT", "SPH_FLOW", "MID", "PID", "FRICTION", "REFSTA", "EREF", "NBCS", "BEM"
        ):
            # /FAIL's second trailing id is its OWN option id in the
            # legacy dialect (read_fail handles it), and /ADMAS headers
            # are /ADMAS/type/admas_ID with NO unit slot (cfg admas.cfg;
            # hm_read_admas.F never uses its UID — read_admas rebinds) —
            # everything else follows the /KEY/.../user_ID/unit_ID
            # convention (except /TABLE where it's dimension/table_id)
            model.raw_unit_refs.append(
                (block.key0, block.user_id, block.unit_id, block.source))
    return model


class ParsedStarterModel(Model):
    """Subclass of Model returned by read_starter_deck supporting (model, log) unpacking."""

    def __iter__(self):
        return iter((self, getattr(self, "log", MessageLog())))


def read_starter_deck(
    source: Union[str, Path, List[KeywordBlock], Any],
    model: Optional[Model] = None,
    log: Optional[MessageLog] = None,
) -> Any:
    """Read a starter deck into a Model, callable as either `model = read_starter_deck(deck)`
    or `model, log = read_starter_deck(deck)`.
    """
    import tempfile
    import os
    from pathlib import Path

    if log is None:
        log = MessageLog()
    target_model = model if model is not None else ParsedStarterModel()
    setattr(target_model, "log", log)

    if isinstance(source, Path):
        source = str(source)

    if isinstance(source, str):
        if "\n" in source or (not os.path.exists(source) and ("/BEGIN" in source or "/MAT" in source)):
            with tempfile.NamedTemporaryFile("w", suffix="_0000.rad", delete=False, encoding="utf-8") as tf:
                tf.write(source)
                tmp_path = tf.name
            try:
                parse_starter_deck(tmp_path, target_model, log)
            finally:
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass
            return target_model

    parse_starter_deck(source, target_model, log)
    return target_model

